    @Test
    void wholeOutcomes() {
        for (String[] r : ROWS) assertEquals(r[1], dump(r[0]), r[0]);
    }

    @Test
    void treeHelpers() {
        AttestXml.Node r = AttestXml.parseXml("<r xmlns:p=\"u\">t<p:x><p:x/>u<y/></p:x><p:x/><y/></r>").root;
        assertEquals(4, r.children.size());
        assertEquals(3, r.elementChildren().size());
        assertEquals(3, r.descendantsNs("u", "x"));
        assertEquals(2, r.descendantsNs("", "y"));
        assertEquals(0, r.descendantsNs("u", "y"));
        AttestXml.Node first = r.elementChildren().get(0);
        AttestXml.Node second = r.elementChildren().get(1);
        AttestXml.Node y = r.elementChildren().get(2);
        r.removeChild(second);
        assertEquals(3, r.children.size());
        assertSame(first, r.elementChildren().get(0));
        assertSame(y, r.elementChildren().get(1));
        assertEquals("t", r.children.get(0).text);
        // a node that is not a child changes nothing
        r.removeChild(new AttestXml.Node());
        r.removeChild(second);
        assertEquals(3, r.children.size());
        r.removeChild(y);
        assertEquals(2, r.children.size());
        assertSame(first, r.children.get(1));
        assertEquals(1, r.elementChildren().size());
    }
